func (q *Queries) UpsertStatus(ctx context.Context, arg UpsertStatusParams) error {
	_, err := q.db.Exec(ctx, upsertStatus,
		arg.SubjectID,
		arg.PurposeID,
		arg.Status,
		arg.PurposeVersionID,
		arg.LastTransactionID,
		arg.Preferences,
		arg.ExpiresAt,
	)
	return err
}
